examples.code:
CREATE SECRET my_sqlite (TYPE adbc, DRIVER 'sqlite', URI ':memory:');
ATTACH '' AS db (TYPE adbc, secret 'my_sqlite');
SELECT * FROM adbc_scan('db', 'SELECT 1 AS id', columns := {'id': 'BIGINT'});
DETACH db;
DROP SECRET my_sqlite;

CREATE SECRET app_db (TYPE adbc, DRIVER 'sqlite', URI 'app.sqlite');
ATTACH 'app.sqlite' AS app (TYPE adbc);
SELECT * FROM adbc_scan('app', 'SELECT 1 AS id', columns := {'id': 'BIGINT'});
DETACH app;
DROP SECRET app_db;
